/* V38: a single compact toolbar inside the existing story header. */
#fs-toolbar{position:absolute;top:5.9%;right:7.1%;z-index:42;display:flex;gap:5px;align-items:center;justify-content:flex-end;pointer-events:auto}
#fs-toolbar button,#fs-toolbar #fs-imgbtn{position:relative!important;top:auto!important;left:auto!important;right:auto!important;bottom:auto!important;flex:0 0 44px!important;display:flex!important;flex-direction:column!important;justify-content:center!important;align-items:center!important;gap:2px!important;width:44px!important;height:47px!important;min-width:0!important;min-height:0!important;margin:0!important;padding:3px 2px!important;background:linear-gradient(155deg,#302716,#090e0a)!important;border:2px ridge #c79c51!important;border-radius:5px!important;box-shadow:0 3px 6px #0009!important;color:#ffefc6!important;font:700 10px/1.12 Georgia,serif!important;letter-spacing:.01em!important;white-space:nowrap!important;cursor:pointer!important;touch-action:manipulation!important}
#fs-toolbar button>span,#fs-toolbar #fs-imgbtn>span{display:block!important;font:normal 20px/1 Georgia,serif!important;color:#f8cf82!important}
#fs-toolbar button:focus-visible,#fs-depth-menu button:focus-visible{outline:3px solid #ffe2a0!important;outline-offset:2px!important}
#fs-toolbar button[aria-pressed="true"]{border-color:#ffe7a1!important;box-shadow:0 0 10px #f0c778aa!important}
#fs-depth-menu[hidden]{display:none!important}
#fs-depth-menu{position:absolute;top:13%;right:7%;z-index:44;width:min(240px,76vw);max-height:50%;overflow-y:auto;display:block;padding:13px!important;border:2px ridge #c69c5b;border-radius:7px;background:linear-gradient(155deg,#25382a,#091912);color:#fff1d4;font:13px/1.37 Georgia,serif;box-shadow:0 6px 24px #000c;pointer-events:auto}
#fs-depth-menu h3{font:700 18px/1.2 Georgia,serif;color:#f8dca0;margin:0 20px 9px 0}
#fs-depth-menu p{font:13px/1.4 Georgia,serif;color:#f7e8c9;margin:7px 0 9px}
#fs-depth-menu .fs-depth-row{display:grid;grid-template-columns:repeat(3,1fr);gap:5px;margin:9px 0}
#fs-depth-menu button{min-height:39px;padding:6px 5px;border:1px solid #c59d5b;border-radius:4px;background:#263a2b;color:#fff2d1;font:700 12px Georgia,serif;cursor:pointer}
#fs-depth-menu button[aria-pressed="true"]{background:#b58a42;color:#20180d;border-color:#ffe1a2}
#fs-depth-menu #fs-depth-tilt{width:100%;margin-top:5px}
#fs-depth-menu #fs-depth-close{position:absolute;top:6px;right:6px;width:28px;height:28px;min-height:28px;font-size:20px;line-height:20px}
#fs-depth-status{font-size:12px!important;color:#ead8b2!important;margin:8px 0 0!important}
#fs-banner>img,#fs-beast>img{transform:perspective(700px) translate3d(var(--fs-3dx,0px),var(--fs-3dy,0px),0) rotateX(var(--fs-3drx,0deg)) rotateY(var(--fs-3dry,0deg)) scale(var(--fs-3dscale,1));transform-origin:center center;transition:transform .14s ease-out}
#fs-banner.fs-depth-gesture{touch-action:none}
@media(max-width:350px){#fs-toolbar{right:5.8%;gap:3px}#fs-toolbar button,#fs-toolbar #fs-imgbtn{width:39px!important;height:44px!important;flex-basis:39px!important;font-size:9.3px!important}#fs-toolbar button>span{font-size:18px!important}#fs-depth-menu{right:6%;width:min(215px,80vw);top:12%}}
@media(prefers-reduced-motion:reduce){#fs-banner>img,#fs-beast>img{transition:none}}

