// Compact MP3 and 3D tools share the existing single-stage UI (no extra overlay of the game).
const toolbar=document.createElement('div');toolbar.id='fs-toolbar';toolbar.setAttribute('role','group');toolbar.setAttribute('aria-label','Bild, Musik und 3D');
const musicButton=document.createElement('button');musicButton.id='fs-mp3btn';musicButton.type='button';musicButton.title='MP3-Player öffnen';musicButton.setAttribute('aria-label','MP3-Player öffnen');musicButton.innerHTML='<span aria-hidden="true">♫</span>MP3';
const depthButton=document.createElement('button');depthButton.id='fs-3dbtn';depthButton.type='button';depthButton.title='3D-Einstellungen';depthButton.setAttribute('aria-label','3D-Tiefeneffekt einstellen');depthButton.innerHTML='<span aria-hidden="true">◇</span>3D';
const oldImageButton=document.getElementById('fs-imgbtn');
toolbar.append(musicButton,depthButton,oldImageButton);stage.appendChild(toolbar);
const depthMenu=document.createElement('section');depthMenu.id='fs-depth-menu';depthMenu.hidden=true;depthMenu.setAttribute('role','dialog');depthMenu.setAttribute('aria-label','3D-Tiefeneffekt');depthMenu.innerHTML='<button type="button" id="fs-depth-close" aria-label="Schließen">×</button><h3>Räumliche Szenen</h3><p>Leichter Tiefeneindruck für Wald und Gegner. Der Buchtext bleibt ruhig und lesbar.</p><div class="fs-depth-row"><button type="button" data-depth="aus">Aus</button><button type="button" data-depth="sanft">Sanft</button><button type="button" data-depth="stark">Stark</button></div><button type="button" id="fs-depth-tilt">iPhone-Neigung aktivieren</button><p id="fs-depth-status" role="status">Du kannst das Bild auch mit dem Finger leicht bewegen.</p>';
stage.appendChild(depthMenu);
let depthMode='aus',tiltInstalled=false,pointerStart=null,pointerMoved=0;
try{const saved=localStorage.getItem('forst-depth-on-stage');if(['aus','sanft','stark'].includes(saved))depthMode=saved;}catch(e){}
function setDepthTransform(x,y){
 const maximum=depthMode==='stark'?12:depthMode==='sanft'?6:0;
 const xx=Math.max(-maximum,Math.min(maximum,x)),yy=Math.max(-maximum,Math.min(maximum,y));
 const z=maximum?1.045:1;
 stage.style.setProperty('--fs-3dx',xx.toFixed(1)+'px');stage.style.setProperty('--fs-3dy',yy.toFixed(1)+'px');
 stage.style.setProperty('--fs-3drx',(-yy/13).toFixed(2)+'deg');stage.style.setProperty('--fs-3dry',(xx/13).toFixed(2)+'deg');stage.style.setProperty('--fs-3dscale',String(z));
}
function syncDepthControls(){
 depthButton.setAttribute('aria-pressed',String(depthMode!=='aus'));
 depthMenu.querySelectorAll('[data-depth]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.depth===depthMode)));
 document.getElementById('fs-banner').classList.toggle('fs-depth-gesture',depthMode!=='aus');
}
function setDepthMode(next){if(!['aus','sanft','stark'].includes(next))return;depthMode=next;try{localStorage.setItem('forst-depth-on-stage',depthMode)}catch(e){};setDepthTransform(0,0);syncDepthControls()}
musicButton.addEventListener('click',()=>{depthMenu.hidden=true;openPanel('music')});
depthButton.addEventListener('click',()=>{depthMenu.hidden=!depthMenu.hidden;syncDepthControls();});
depthMenu.querySelector('#fs-depth-close').addEventListener('click',()=>{depthMenu.hidden=true});
depthMenu.querySelectorAll('[data-depth]').forEach(b=>b.addEventListener('click',()=>setDepthMode(b.dataset.depth)));
const depthStatus=depthMenu.querySelector('#fs-depth-status');
depthMenu.querySelector('#fs-depth-tilt').addEventListener('click',async()=>{
 if(depthMode==='aus')setDepthMode('sanft');
 if(tiltInstalled){depthStatus.textContent='Neigung ist bereits aktiviert.';return;}
 if(!('DeviceOrientationEvent' in window)){depthStatus.textContent='Kein Bewegungssensor verfügbar. Fingerbewegung funktioniert weiterhin.';return;}
 try{
  if(typeof DeviceOrientationEvent.requestPermission==='function'){
   const allowed=await DeviceOrientationEvent.requestPermission();
   if(allowed!=='granted'){depthStatus.textContent='Nicht freigegeben. Fingerbewegung ist weiterhin möglich.';return;}
  }
  window.addEventListener('deviceorientation',e=>{
   if(depthMode==='aus'||!depthMenu.isConnected)return;
   const gamma=Number(e.gamma)||0,beta=Number(e.beta)||0;
   const m=depthMode==='stark'?12:6;
   setDepthTransform(Math.max(-1,Math.min(1,gamma/32))*m,Math.max(-1,Math.min(1,(beta-30)/38))*m);
  },{passive:true});
  tiltInstalled=true;depthStatus.textContent='Neigung aktiv: Bewege dein iPhone langsam.';
 }catch(e){depthStatus.textContent='Sensorfreigabe nicht möglich. Fingerbewegung bleibt nutzbar.';}
});
const banner=document.getElementById('fs-banner');
banner.addEventListener('pointerdown',e=>{pointerStart={x:e.clientX,y:e.clientY};pointerMoved=0},{passive:true});
banner.addEventListener('pointermove',e=>{
 if(depthMode==='aus')return;
 const rect=banner.getBoundingClientRect();if(!rect.width)return;
 const m=depthMode==='stark'?12:6;
 setDepthTransform(((e.clientX-rect.left)/rect.width-.5)*2*m,((e.clientY-rect.top)/rect.height-.5)*2*m);
 if(pointerStart&&e.pointerType==='touch')pointerMoved=Math.max(pointerMoved,Math.abs(e.clientX-pointerStart.x),Math.abs(e.clientY-pointerStart.y));
},{passive:true});
banner.addEventListener('click',e=>{if(pointerMoved>9&&depthMode!=='aus'){e.preventDefault();e.stopImmediatePropagation()}pointerMoved=0;pointerStart=null;},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')depthMenu.hidden=true});
syncDepthControls();
